#!/usr/bin/env python3
"""Writes docs/CONFORMANCE.md from docs/conformance_run.json (the evidence of tools/conformance.py) and docs/traceability.json.
Nothing in the report is typed by hand except the fixed explanatory text."""
import json, os, subprocess, sys
ROOT = os.path.join(os.path.dirname(__file__), "..")
run = json.load(open(f"{ROOT}/docs/conformance_run.json"))
reg = json.load(open(f"{ROOT}/docs/traceability.json"))["requirements"]
st = {}
for r in reg: st[r["status"]] = st.get(r["status"], 0) + 1
S = run["suites"]; tot_pass = sum(int(str(s["passed"]).split()[0]) for s in S if str(s["passed"]).split()[0].isdigit())
L = ["# Conformance and acceptance report", "",
 f"Generated by `tools/conf_report.py` from `docs/conformance_run.json` (run `tools/conformance.py`, started {run['started']}, finished {run.get('finished','(unfinished)')}, host {run['host']}, {run['cpus']} CPUs). Each stack suite ran on a freshly restarted stack. Result: **{'ALL SUITES PASSED' if run.get('all_ok') else 'SOME SUITES FAILED'}** ({sum(s['ok'] for s in S)} of {len(S)} suites, {tot_pass} individual checks/tests counted; Go counts packages, not tests).", "",
 "## Suites", "", "| Group | Suite | Passed | Failed | Seconds | Result |", "|---|---|---|---|---|---|"]
for s in S: L.append(f"| {s['group']} | {s['name']} | {s['passed']} | {s['failed']} | {s['seconds']} | {'pass' if s['ok'] else '**FAIL**'} |")
L += ["", "## Requirements covered", "", f"`docs/TRACEABILITY.md` maps {len(reg)} requirements (the 22 brief items, the standing rules and the Definition of Done) to code, tests, live suites, benchmarks and UI screens, and fails if any reference dangles or if a suite it cites did not pass in this run. Self-assessed status: " + ", ".join(f"{v} {k}" for k, v in sorted(st.items())) + ".", "",
 "## Mapping to the EOI scoring", "",
 "The EOI scoring rubric (criteria, weights, the 80 % technical share) was **not part of the brief or the repository**, so no score is stated here and none was invented. `docs/eoi_weights.csv` is a template with one row per brief item and blank weights; once the real criteria and weights are entered, `tools/eoi_score.py` computes the score from the traceability statuses. By default a criterion earns full credit only if every requirement it lists is `met`, and `partial` earns zero (conservative; change it in the file if the EOI says otherwise).", "",
 "## What this report does not show", "",
 "- Every test ran on this development host against our own simulators and synthetic or public IEEE data. Nothing ran against vendor equipment, a real utility model, third-party protocol conformance suites (IEC 60870-5-104/101 test suites, DNP3 conformance, CGMES tools) or a real operator population.",
 "- Several suites are self-written checks of our own code (DAST, SAST, fuzzers). They find what we thought of; they are not a CERT-In VAPT or an independent source audit, and passing them is not certification.",
 "- The 7-day soak was not run; the harness self-test passed.",
 "- `partial` rows in the traceability matrix state what is missing. ICCP/TASE.2, IEC 61850 MMS and OPC UA are not built.",
 "- The usability study has not been run (no participants): see `docs/USABILITY.md`.", "",
 "## Reproduce", "", "```", "tools/conformance.py              # about 1 hour on 2 cores; restarts the stack many times", "tools/trace.py                    # traceability check, writes docs/TRACEABILITY.md", "tools/conf_report.py              # this file", "tools/eoi_score.py                # after filling docs/eoi_weights.csv", "```", ""]
open(f"{ROOT}/docs/CONFORMANCE.md", "w").write("\n".join(L))
print("wrote docs/CONFORMANCE.md")
